import{_ as i,C as s,o as n,c as r,j as a,a as t,E as l,a6 as d}from"./chunks/framework.BHBQfcoO.js";const c="/releases/2026.05.09.1/connectivity-overlay.webm",y=JSON.parse('{"title":"LCARdS 2026.05.09.1","description":"Connectivity overlay effects, card portal action, HA-LCARS theme profiles, CSS sizing expressions.","frontmatter":{"version":"2026.05.09.1","date":"2026-05-09T00:00:00.000Z","status":"released","summary":"Connectivity overlay effects, card portal action, HA-LCARS theme profiles, CSS sizing expressions.","breaking":false},"headers":[],"relativePath":"releases/2026.05.09.1.md","filePath":"releases/2026.05.09.1.md"}'),h={name:"releases/2026.05.09.1.md"};function u(m,e,f,p,v,b){const o=s("ReleaseMeta");return n(),r("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-05-09-1",tabindex:"-1"},[t("LCARdS 2026.05.09.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-05-09-1","aria-label":'Permalink to "LCARdS 2026.05.09.1"'},"​")],-1)),l(o),e[1]||(e[1]=a("h2",{id:"new-features",tabindex:"-1"},[t("New Features "),a("a",{class:"header-anchor",href:"#new-features","aria-label":'Permalink to "New Features"'},"​")],-1)),e[2]||(e[2]=a("p",null,[a("strong",null,"Fix:"),t(" Slider zero-height issue from 2026.05.08.2 has been fixed")],-1)),e[3]||(e[3]=a("h4",{id:"connectivity-overlay-effects",tabindex:"-1"},[t("Connectivity Overlay Effects "),a("a",{class:"header-anchor",href:"#connectivity-overlay-effects","aria-label":'Permalink to "Connectivity Overlay Effects"'},"​")],-1)),e[4]||(e[4]=a("ul",null,[a("li",null,"The Connectivity Overlay Effects (LCARdS Config Panel → Connectivity tab) bring customizable fullscreen effects that play on disconnection/reconnection with the Home Assistant server."),a("li",null,"Choose from a variety of effects such as custom stylized text and HA card(s) - can be scoped by device/user - great for kiosk installs.")],-1)),e[5]||(e[5]=a("p",null,[a("video",{class:"release-shot",src:c,title:"Connectivity overlay effect on disconnect",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[6]||(e[6]=d('<h4 id="card-portal" tabindex="-1">Card Portal <a class="header-anchor" href="#card-portal" aria-label="Permalink to &quot;Card Portal&quot;">​</a></h4><p>The core system behind Connectivity Overlay and the Alert Overlay systems, is now available as an HA Action.</p><ul><li>Create your own customized overlays with fully configurable effect layers and cards.</li><li>Trigger from automations or card actions - and scope to any device/user.</li><li>Useful for simple use-cases where browser_mod is not required.</li></ul><h4 id="ha-lcars-theme-profiles" tabindex="-1">HA-LCARS Theme Profiles <a class="header-anchor" href="#ha-lcars-theme-profiles" aria-label="Permalink to &quot;HA-LCARS Theme Profiles&quot;">​</a></h4><ul><li>Two custom LCARdS theme profiles for <strong>HA-LCARS</strong> have been added.</li><li>In Picard style, these coordinate the LCARdS colour palette with the HA-LCARS theme and the core HA colour palette that HA uses to derive other UI colours.</li><li>Two accent modes are provided (Red/Blue) and both support Light/Dark mode in Home Assistant.</li><li>See <a href="/configuration/ha-lcars-theme-profiles.html"><strong>Configuration → HA-LCARS Theme Profiles</strong></a> for setup instructions and a full YAML.</li></ul><h4 id="card-sizing-max-width-max-height-css-expressions" tabindex="-1">Card Sizing: <code>max_width</code>/<code>max_height</code> &amp; CSS Expressions <a class="header-anchor" href="#card-sizing-max-width-max-height-css-expressions" aria-label="Permalink to &quot;Card Sizing: `max_width`/`max_height` &amp; CSS Expressions&quot;">​</a></h4><ul><li>Cards now accept <code>max_width</code> and <code>max_height</code> when it is desired to limit card dimensions when autosizing in containers.</li><li>Dimension configuration values can now be any CSS length expression: pixels, viewport units, <code>clamp()</code>, <code>calc()</code>, percentages, etc.</li><li>This opens up possibilities such as adaptable elbow widths, etc.</li></ul><h4 id="button-enhancements" tabindex="-1">Button Enhancements <a class="header-anchor" href="#button-enhancements" aria-label="Permalink to &quot;Button Enhancements&quot;">​</a></h4><ul><li>Border Hover &amp; Pressed States: Button border colours can now respond to interaction state.</li><li>Button Default Label: The default stub label for new Button cards is now a randomly chosen placeholder such as <code>3E-F2A</code> instead of the static <code>&#39;LCARdS&#39;</code> string (similar to CB-LCARS auto-generated labels)</li><li>New convenience presets <code>panel-light</code> &amp; <code>panel-dark</code> which are preconfigured buttons to be used in decorative mode. They have hover and interactive effects default disabled.</li></ul><h4 id="font-rendering-improvements" tabindex="-1">Font Rendering Improvements <a class="header-anchor" href="#font-rendering-improvements" aria-label="Permalink to &quot;Font Rendering Improvements&quot;">​</a></h4><ul><li>Several Alien fonts have had a <code>size-adjust</code> property adjustment in the <code>@font-face</code> declarations. Improving size equivalency with other fonts. Please report any issues or adjustment suggestions.</li></ul><hr><h3 id="updates-fixes" tabindex="-1">Updates &amp; Fixes <a class="header-anchor" href="#updates-fixes" aria-label="Permalink to &quot;Updates &amp; Fixes&quot;">​</a></h3><ul><li>Slider: fix autosizing resize loop in dimensionless parent (ie. custom-layout-card)</li><li>More documentation updates</li><li>CI: add documentation validation for broken links; validation of examples against card schema in the code</li><li>several other small fixes an improvements</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.04.25.1...2026.05.09.1" target="_blank" rel="noreferrer">2026.04.25.1...2026.05.09.1</a></p>',16))])}const C=i(h,[["render",u]]);export{y as __pageData,C as default};
